<?phpnamespace App\Controllers\Admin;use App\Controllers\{AdminController};use App\Models\{ Help, User, Helpc };use App\Utils\{ Telegram, DatatablesHelper };use App\Services\Mail;use Ozdemir\Datatables\Datatables;use Exception;class HelpController extends AdminController{    public function index($request, $response, $args)    {            $table_config['total_column'] = array(            'op' => '操作',             'id' => 'ID',            'title' => '标题',             'content' => '内容',             'class' => '分类',             'add_time' => '创建时间',            'ontop' => '是否置顶',            'sort' => '排序',        );        $table_config['default_show_column'] = array(            'op',             'id',            'title',             'content',            'class',            'add_time',            'ontop',            'sort',        );                $table_config['ajax_url'] = '/admin/help/document/ajax';        return $this->view()->assign('table_config', $table_config)->display('admin/help/document/index.tpl');    }    public function create($request, $response, $args)    {        $helpClass = Helpc::where('pageshow', '1')->orderBy('id', 'asc')->get();        return $this->view()->assign('helpClass', $helpClass)->display('admin/help/document/create.tpl');    }    public function add($request, $response, $args)    {        $title   = $request->getParam('title');        $content = $request->getParam('content');        $markdown = $request->getParam('markdown');        $class  = $request->getParam('class');        $ontop   = $request->getParam('isontop');        $sort    = $request->getParam('sort');        if ($class==0) {            $rs['ret'] = 0;            $rs['msg'] = '请选择分类';            return $response->getBody()->write(json_encode($rs));        }        $help = new Help();        $help->title = $title;        $help->content = htmlspecialchars_decode($content);           $help->markdown = $markdown;        $help->class = $class;        $help->ontop = $ontop;        $help->add_time = date('Y-m-d H:i:s');        $help->sort = $sort;                if (!$help->save()) {            $rs['ret'] = 0;            $rs['msg'] = '添加失败';            return $response->getBody()->write(json_encode($rs));        }                $rs['ret'] = 1;        $rs['msg'] = '添加成功';        return $response->getBody()->write(json_encode($rs));    }    public function edit($request, $response, $args)    {        $id = $args['id'];        $help = Help::find($id);        $helpClass = Helpc::where('pageshow', '1')->orderBy('id', 'asc')->get();   /* 列出所有分类 */                $helpUpid = Helpc::where('id', $help->class)->value('id');        return $this->view()            ->assign('help', $help)            ->assign('helpUpid', $helpUpid)            ->assign('helpClass', $helpClass)            ->display('admin/help/document/edit.tpl');    }    public function update($request, $response, $args)    {        $title = $request->getParam('title');        $content = $request->getParam('content');        $markdown = $request->getParam('markdown');        $class = $request->getParam('class');        $ontop = $request->getParam('isontop');        $sort  = $request->getParam('sort');                if ($class==0) {            $rs['ret'] = 0;            $rs['msg'] = '请选择分类';            return $response->getBody()->write(json_encode($rs));        }        $id = $args['id'];        $help = Help::find($id);        $help->title = $title;        $help->content = htmlspecialchars_decode($content);        $help->markdown = $markdown;        $help->class = $class;        $help->ontop = $ontop;        $help->add_time = date('Y-m-d H:i:s');        $help->sort = $sort;                if (!$help->save()) {            $rs['ret'] = 0;            $rs['msg'] = '修改失败';            return $response->getBody()->write(json_encode($rs));        }        $rs['ret'] = 1;        $rs['msg'] = '修改成功';        return $response->getBody()->write(json_encode($rs));    }    public function delete($request, $response, $args)    {        $id = $request->getParam('id');        $help = Help::find($id);        if (!$help->delete()) {            $rs['ret'] = 0;            $rs['msg'] = '删除失败';            return $response->getBody()->write(json_encode($rs));        }        $rs['ret'] = 1;        $rs['msg'] = '删除成功';        return $response->getBody()->write(json_encode($rs));    }    public function ajax($request, $response, $args)    {        $datatables = new Datatables(new DatatablesHelper());        $datatables->query('Select id as op,id,title,content,class,add_time,ontop,sort from help');        $datatables->edit('op', static function ($data) {            return '<a class="btn btn-brand" href="/admin/help/document/' . $data['id'] . '/edit">编辑</a>                    <a class="btn btn-brand-accent" id="delete" value="' . $data['id'] . '" href="javascript:void(0);" onClick="delete_modal_show(\'' . $data['id'] . '\')">删除</a>';        });        $datatables->edit('class', static function ($data) {            $class = Helpc::where('id', $data['class'])->first();            return $class->name;        });        $body = $response->getBody();        $body->write($datatables->generate());    }    public function getHelpClass($request, $response, $args)    {        $id = $request->getParam('id');        if (!$id) {            $res = Helpc::where('upid', '=', 0)->orderBy('id', 'asc')->get();            return $response->getBody()->write(json_encode($res));        }        $helpClass2s = Helpc::where('upid', '=', $id)->orderBy('id', 'asc')->get();        if (count($helpClass2s) == 0) {            $res['ret'] = 0;            $res['msg'] = '该分类没有数据';            return $response->getBody()->write(json_encode($res));        }        return $response->getBody()->write(json_encode($helpClass2s));    }    /**     * 分类管理     */    public function class_index($request, $response, $args)    {        $table_config['total_column'] = array(            'op' => '操作',             'id' => 'ID',            'name' => '分类名称',             'li' => '图标',             'pageshow' => '页面显示',            'sort' => '排序',        );        $table_config['default_show_column'] = array(            'op',             'id',            'name',             'li',            'pageshow',            'sort',        );                $table_config['ajax_url'] = '/admin/help/class/ajax';        return $this->view()->assign('table_config', $table_config)->display('admin/help/class/index.tpl');    }    public function class_create($request, $response, $args)    {        return $this->view()->display('admin/help/class/create.tpl');    }    public function class_add($request, $response, $args)    {        $name     = $request->getParam('name');        $pageshow = $request->getParam('pageshow');        $ico      = $request->getParam('ico');        $sort     = $request->getParam('sort');        $explain  = $request->getParam('explain');                if (!$name) {            $rs['ret'] = 0;            $rs['msg'] = '分类名称不能为空';            return $response->getBody()->write(json_encode($rs));        }                $helpc           = new Helpc();        $helpc->name     = $name;        $helpc->pageshow = $pageshow;        $helpc->li       = $ico;        $helpc->sort     = $sort;        $helpc->explain  = $explain;                if (!$helpc->save()) {            $rs['ret'] = 0;            $rs['msg'] = '添加失败';            return $response->getBody()->write(json_encode($rs));        }                $rs['ret'] = 1;        $rs['msg'] = '添加成功';        return $response->getBody()->write(json_encode($rs));    }    public function class_edit($request, $response, $args)    {        $id = $args['id'];        $helpc = Helpc::find($id);        return $this->view()            ->assign('helpc', $helpc)            ->display('admin/help/class/edit.tpl');    }        public function class_update($request, $response, $args)    {        $name     = $request->getParam('name');        $pageshow = $request->getParam('pageshow');        $ico      = $request->getParam('ico');        $sort     = $request->getParam('sort');        $explain     = $request->getParam('explain');        if (!$name) {            $rs['ret'] = 0;            $rs['msg'] = '分类名称不能为空';            return $response->getBody()->write(json_encode($rs));        }        $id              = $args['id'];        $helpc           = Helpc::find($id);        $helpc->name     = $name;        $helpc->pageshow = $pageshow;        $helpc->li       = $ico;        $helpc->sort     = $sort;        $helpc->explain  = $explain;        if (!$helpc->save()) {            $rs['ret'] = 0;            $rs['msg'] = '修改失败';            return $response->getBody()->write(json_encode($rs));        }                $rs['ret'] = 1;        $rs['msg'] = '修改成功';        return $response->getBody()->write(json_encode($rs));    }    public function class_delete($request, $response, $args)    {        $id = $request->getParam('id');        $helpc = Helpc::find($id);                if (!$helpc->delete()) {            $rs['ret'] = 0;            $rs['msg'] = '删除失败';            return $response->getBody()->write(json_encode($rs));        }        $rs['ret'] = 1;        $rs['msg'] = '删除成功';        return $response->getBody()->write(json_encode($rs));    }    public function class_ajax($request, $response, $args)    {        $datatables = new Datatables(new DatatablesHelper());        $datatables->query('Select id as op,id,name,li,pageshow,sort from help_class');        $datatables->edit('op', static function ($data) {            return '<a class="btn btn-brand" href="/admin/help/class/' . $data['id'] . '/edit">编辑</a>                    <a class="btn btn-brand-accent" id="delete" value="' . $data['id'] . '" href="javascript:void(0);" onClick="delete_modal_show(\'' . $data['id'] . '\')">删除</a>';        });        $datatables->edit('pageshow', static function ($data) {                $name = ($data['pageshow'] ? $data['pageshow'] === 2 ? '回收站' : '显示' : '不显示');            return $name;        });        $body = $response->getBody();        $body->write($datatables->generate());    }}